INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (4424, 'Three Best Friends', 'en', 'Three best friends always did everything together until one time when the bush swallowed up one of them. Nível: First paragraphs. Ilustração: Wiehan de Jager, Idowu Abayomi Oluwasegun, Andrews Opoku Antwi, Michelangelo Quaye Anang and Rob Owen.', 'https://africanstorybook.org/illustrations/covers/23002.png', NULL, 1436, 23, 18, 'asp-23002', 'cc-by', 0, NULL);
